// The watch list of a Windows machine (docs/agent.md → Windows: PowerShell only), as the hub checks it before it
// prints specs.txt (scripts/agent-specs.mjs --platform windows) and as the Windows agent checks it on the machine at
// every start (Test-AgentSpecs in HomeHubAgent.psm1). The PowerShell side cannot import this file, so the two are held
// together by test vectors (tests/fixtures/agent-windows/vectors.json) and by the rules file the agent reads
// (report-rules.json, generated by rules.mjs from the same constants).
//
// The line format is validateSpecs's (server/agent-report.mjs, frozen): "id|kind|a|b|label", "\n" after each line, an
// empty list an empty file. validateSpecs knows no Windows kinds and is frozen, so the id and the label are checked by
// validateSpecs itself, on a Linux line made of them (its label rule is the Windows one: no system/ prefix); the kind
// and the arguments are the Windows rules:
//   winreg   a = a display name (WINREG_NAME, server/watch-rules.mjs), b = empty; label = a Windows service name or empty
import {validateSpecs} from '../../../server/agent-report.mjs';
import {WINREG_NAME} from '../../../server/watch-rules.mjs';

export const WINDOWS_SPEC_KINDS=Object.freeze(['winreg']);

/** specs.txt of a Windows machine → {ok, lines, errors:[{line, reason}]}, the shape and reasons of validateSpecs. */
export function validateWindowsSpecs(text){
 const errors=[],lines=[];
 if(typeof text!=='string')return {ok:false,lines,errors:[{line:0,reason:'not text'}]};
 if(text==='')return {ok:true,lines,errors};
 if(!text.endsWith('\n'))return {ok:false,lines,errors:[{line:0,reason:'the file must end with a newline'}]};
 text.slice(0,-1).split('\n').forEach((line,i)=>{
  const n=i+1,no=reason=>errors.push({line:n,reason});
  const f=line.split('|');if(f.length!==5)return no('a line is id|kind|a|b|label');
  const [id,kind,a,b,label]=f;
  // The id and the label by validateSpecs's own rules: a Linux json line with this id and label.
  const generic=validateSpecs(`${id}|json|/x||${label}\n`,{platform:'linux'});
  const reason=generic.ok?null:generic.errors[0].reason;
  if(reason==='id')return no('id');
  if(!WINDOWS_SPEC_KINDS.includes(kind))return no('kind');
  if(reason)return no(reason==='label'?'label':'arguments');
  if(!(WINREG_NAME.test(a)&&b===''))return no('arguments');
  lines.push(line);
 });
 return {ok:errors.length===0,lines:errors.length?[]:lines,errors};
}

// One character of a name as .NET's OrdinalIgnoreCase compares it: its simple upper case (one character), else itself.
const upper=s=>Array.from({length:s.length},(_,i)=>{const u=s[i].toUpperCase();return u.length===1?u:s[i];}).join('');
/** Does a winreg display name (WINREG_NAME) match an uninstall entry's DisplayName? The agent's Test-DisplayName in
 *  JavaScript: the whole name, ignoring case; * any run of characters. The pieces between the * are found leftmost
 *  first with a plain search, which is exact for a pattern whose only wildcard is * and takes time linear in the
 *  name per piece: no regular expression, so no rule can make the agent backtrack for minutes. The vectors
 *  (vectors.json → names) hold the two to one answer. */
export function matchDisplayName(pattern,name){
 const pieces=upper(pattern).split('*'),n=upper(name);
 if(pieces.length===1)return n===pieces[0];
 const first=pieces[0],last=pieces.at(-1);
 if(n.length<first.length+last.length||!n.startsWith(first)||!n.endsWith(last))return false;
 let pos=first.length;const end=n.length-last.length;
 for(const piece of pieces.slice(1,-1)){
  if(!piece)continue;
  const at=n.indexOf(piece,pos);
  if(at<0||at+piece.length>end)return false;
  pos=at+piece.length;
 }
 return true;
}
